with base as (select id, supplier_name, country, city, rating, coalesce(rating, 0) as rating_filled, coalesce(city, 'N/A') as resolved_city from suppliers where city is not null and city is distinct from 'Tokyo') select id, rating_filled, resolved_city, count(rating) over (partition by city) as city_count_rating, count(rating_filled) over w_hist as country_count_rating_filled from base where city = 'Singapore' window w_hist as (partition by country, city)
